import java.util.concurrent.*;

public class Test {
    public static void main(String[] args) throws Exception {
        Exchanger<String> exchanger = new Exchanger<>();
        ExecutorService service = Executors.newFixedThreadPool(2);
        service.submit(() -> {
            try {
                String received = exchanger.exchange("A");
                System.out.println(received);
            } catch (Exception e) {}
        });
        service.submit(() -> {
            try {
                String received = exchanger.exchange("B");
                System.out.println(received);
            } catch (Exception e) {}
        });
        Thread.sleep(100);
        service.shutdown();
    }
},"A and B printed","Compilation error","Runtime error","Nothing prints"

