import java.util.*;
import java.util.concurrent.*;

public class Test {
    public static void main(String[] args) throws Exception {
        BlockingQueue<Integer> queue = new SynchronousQueue<>();
        ExecutorService service = Executors.newFixedThreadPool(2);
        service.submit(() -> {
            try {
                queue.put(1);
                System.out.println("Put complete");
            } catch (Exception e) {}
        });
        Thread.sleep(100);
        service.submit(() -> {
            try {
                System.out.println(queue.take());
            } catch (Exception e) {}
        });
        Thread.sleep(100);
        service.shutdown();
    }
},"Put complete and 1 printed","Compilation error","Runtime error","Program hangs"

What is the result?
